contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= 2 * amount);

        c.lockInGuess{value: amount}(keccak256(abi.encodePacked(uint(123))));

        bool secondReverted;
        try c.lockInGuess{value: amount}(keccak256(abi.encodePacked(uint(456)))) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(secondReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

    receive() external payable {}
}
